export const getRespondToRemediationUrl = (activityId: string,) => {




  return `/api/remediation/${activityId}/respond`
}

/**
 * @summary Submit a remediation response and receive a follow-up
 */
export const respondToRemediation = async (activityId: string,
    remediationResponseInput: RemediationResponseInput, options?: Parameters<typeof customFetch>[1]): Promise<RemediationResult> => {

  return customFetch<RemediationResult>(getRespondToRemediationUrl(activityId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(remediationResponseInput)
  }
);}





export const getRespondToRemediationMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof respondToRemediation>>, TError,{activityId: string;data: BodyType<RemediationResponseInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof respondToRemediation>>, TError,{activityId: string;data: BodyType<RemediationResponseInput>}, TContext> => {

const mutationKey = ['respondToRemediation'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof respondToRemediation>>, {activityId: string;data: BodyType<RemediationResponseInput>}> = (props) => {
          const {activityId,data} = props ?? {};

          return  respondToRemediation(activityId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RespondToRemediationMutationResult = NonNullable<Awaited<ReturnType<typeof respondToRemediation>>>
    export type RespondToRemediationMutationBody = BodyType<RemediationResponseInput>
